    ('186eeb54-e6a0-4370-87c6-fbcaae023a33'::uuid, 'period_name', NULL, '4500 - 3000 BC', 'fields-wd3-2026-10-02b-s002:186eeb54-e6a0-4370-87c6-fbcaae023a33:period_name', 'fields-wd3-2026-10-02b-s002 (wd3-derive-period-name): period_start -4000 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(-4000) = ''4500 - 3000 BC''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0052)", "decision": "replace", "status": "MISSING", "reasoning": "The Galmpton & Churston District Local History Group page (an excerpt of John Risdon''s book on the parish of Churston Ferrers with Galmpton) says the Broadsands Neolithic Chamber Tomb was constructed between 4,000 and 3,000 B.C.; the start of that range is 4000 BC. The live page sits behind a bot challenge, so the quote is taken from its Internet Archive copy.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('186eeb54-e6a0-4370-87c6-fbcaae023a33'::uuid, 'period_start', NULL, '-4000', 'fields-wd3-2026-10-02b-s002:186eeb54-e6a0-4370-87c6-fbcaae023a33:period_start', 'fields-wd3-2026-10-02b-s002 (wd3-replace): None -> ''-4000''', '[{"source": "https://web.archive.org/web/2024/https://www.galmptonandchurstonhistory.org.uk/broadsands-neolithic-chamber-tomb/", "url": "https://web.archive.org/web/2024/https://www.galmptonandchurstonhistory.org.uk/broadsands-neolithic-chamber-tomb/", "quote": "Constructed some time in the late Stone Age between 4,000 and 3,000 B.C.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0052)", "decision": "replace", "status": "MISSING", "reasoning": "The Galmpton & Churston District Local History Group page (an excerpt of John Risdon''s book on the parish of Churston Ferrers with Galmpton) says the Broadsands Neolithic Chamber Tomb was constructed between 4,000 and 3,000 B.C.; the start of that range is 4000 BC. The live page sits behind a bot challenge, so the quote is taken from its Internet Archive copy.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('1876d7d8-2561-4f0b-8278-f89293aecbb7'::uuid, 'site_type', NULL, 'Fort', 'fields-wd3-2026-10-02b-s002:1876d7d8-2561-4f0b-8278-f89293aecbb7:site_type', 'fields-wd3-2026-10-02b-s002 (wd3-replace): None -> ''Fort''', '[{"source": "https://en.wikipedia.org/wiki/Lee_Wood", "url": "https://en.wikipedia.org/wiki/Lee_Wood", "quote": "Lee Wood is the location of an Iron Age enclosure or hill fort situated near to Braunton and Barnstaple in Devon, England.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0087)", "decision": "replace", "status": "MISSING", "reasoning": "Wikipedia describes Lee Wood near Braunton, Devon as an Iron Age enclosure or hill fort and then calls it the fort; the most specific canonical type is Fort.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('18911cb2-dff1-4d14-9110-de55c40706c0'::uuid, 'period_name', NULL, '1 - 500 AD', 'fields-wd3-2026-10-02b-s002:18911cb2-dff1-4d14-9110-de55c40706c0:period_name', 'fields-wd3-2026-10-02b-s002 (wd3-derive-period-name): period_start 301 (written in this step)', '[{"source": "pipeline/utils/text.py:categorize_period", "url": "pipeline/utils/text.py", "quote": "categorize_period(301) = ''1 - 500 AD''"}, {"source": "output/remediation/gold_standard/GOLD_STANDARD.md:79", "url": "output/remediation/gold_standard/GOLD_STANDARD.md", "quote": "| `period_name` | equals `categorize_period(period_start)` |"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0075)", "decision": "replace", "status": "MISSING", "reasoning": "Malton Museum places the construction of the Yorkshire-coast fortlets (signal stations), naming Goldsborough among them (the Roman signal station of Goldsborough, Lythe, near Whitby), in the late 4th century after Theodosius''s mission of AD 367; the century is given as its first year, 301. The Wikipedia hamlet article itself gives no date; the ancient site there is the signal station.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
    ('18911cb2-dff1-4d14-9110-de55c40706c0'::uuid, 'period_start', NULL, '301', 'fields-wd3-2026-10-02b-s002:18911cb2-dff1-4d14-9110-de55c40706c0:period_start', 'fields-wd3-2026-10-02b-s002 (wd3-replace): None -> ''301''', '[{"source": "https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/", "url": "https://www.maltonmuseum.co.uk/2021/05/29/the-fortlets-signal-stations-along-the-yorkshire-coast/", "quote": "During the late 4th century Roman Britain was being attacked from land and sea by the Picts, the Attacotti, the Scots, the Franks and the Saxons. The historian Ammianus Marcellinus paints a picture of a chaotic situation with bands of raiders wandering around unchecked, taking prisoners and loot where they fancied, and destroying or killing at will. In AD 367 the Emperor Valentinian dispatched a task force to try to get a grip on the situation, placing Theodosius (the father of the future Emperor Theodosius the Great) in command. Ammianus Marcellinus wrote that, on his arrival, Theodosius ‘rendered the greatest aid to the troubled and confused fortunes of the Britons’ including restoring ‘cities and garrison towns…and protected the borders with guard-posts and defence works’. Figure 1: Inscription from Ravenscar Along the Yorkshire coast a system of fortlets (often referred to as `signal stations`) were constructed. Archaeological remains of such structures have been found at Scarborough, Filey, Goldsborough and Huntcliffe.", "outcome": "found"}, {"source": "WD3 decision (counted, round 0, wd3-r0-b0075)", "decision": "replace", "status": "MISSING", "reasoning": "Malton Museum places the construction of the Yorkshire-coast fortlets (signal stations), naming Goldsborough among them (the Roman signal station of Goldsborough, Lythe, near Whitby), in the late 4th century after Theodosius''s mission of AD 367; the century is given as its first year, 301. The Wikipedia hamlet article itself gives no date; the ancient site there is the signal station.", "value_page": null, "model": "anthropic/claude-sonnet-5-5 (Claude Code agent)"}]'::jsonb),
